[{"order":1,"type":"heading","text":"Mastering Custom CSS and JS Transitions in Svelte"},{"order":2,"type":"paragraph","text":"Svelte provides a powerful built-in transition system that allows you to create smooth animations using both CSS and JavaScript. Unlike traditional frameworks where you need heavy third-party libraries, Svelte compiles animations down to highly efficient vanilla DOM manipulations."},{"order":3,"type":"subheading","text":"1. Understanding CSS Transitions in Svelte"},{"order":4,"type":"paragraph","text":"The simplest way to animate elements when they enter or leave the DOM is by using the 'transition' directive combined with a CSS transition function."},{"order":5,"type":"code","text":"<script>
  import { fade } from 'svelte/transition';
  let visible = true;
</script>

<button on:click="{() => visible = !visible}">Toggle</button>

{#if visible}
  <div transition:fade>
    Fading in and out
  </div>
{/if}"},{"order":6,"type":"subheading","text":"2. Creating a Custom CSS Transition"},{"order":7,"type":"paragraph","text":"Svelte allows you to define custom CSS transitions by passing a function that returns an object containing 'duration', 'delay', 'easing', and a 'css' property. The 'css' function receives the 't' argument (progress from 0 to 1) and 'u' (1 - t)."},{"order":8,"type":"code","text":"<script>
  function spin(node, { duration = 400 }) {
    return {
      duration,
      css: t => {
        const eased = t;
        return `
          transform: scale(${eased}) rotate(${eased * 1080}deg);
          opacity: ${t};
        `;
      }
    };
  }

  let visible = true;
</script>

<button on:click="{() => visible = !visible}">Toggle Spin</button>

{#if visible}
  <div in:spin="{{ duration: 800 }}">
    Custom Spinning Box
  </div>
{/if}"},{"order":9,"type":"subheading","text":"3. JavaScript-based Transitions"},{"order":10,"type":"paragraph","text":"For complex animations, such as canvas or WebGL effects where CSS is not enough, Svelte supports JavaScript-driven transitions using the 'tick' property instead of 'css'."},{"order":11,"type":"code","text":"<script>
  function typewriter(node, { speed = 50 }) {
    const valid = node.childNodes.length === 1 && node.childNodes[0].nodeType === Node.TEXT_NODE;

    if (!valid) {
      throw new Error('This transition only works on elements with a single text node');
    }

    const text = node.textContent;
    const length = text.length;

    return {
      duration: length * speed,
      tick: t => {
        const i = Math.trunc(text.length * t);
        node.textContent = text.slice(0, i);
      }
    };
  }

  let visible = true;
</script>

<button on:click="{() => visible = !visible}">Toggle Typewriter</button>

{#if visible}
  <p transition:typewriter="{{ speed: 100 }}">
    The quick brown fox jumps over the lazy dog.
  </p>
{/if}"},{"order":12,"type":"bullet_point","text":"Use CSS transitions for layout changes, opacity, transforms, and simple UI feedback."},{"order":13,"type":"bullet_point","text":"Use JS transitions when manipulating text content, SVG paths, or integrating with physics libraries."},{"order":14,"type":"bullet_point","text":"Always clean up timers and subscriptions inside the transition return object if necessary."}]
